mapper.select:
SELECT BATCH_ID, SOURCE_NAME, FILE_TYPE, PART_NO, BYTE_COUNT, RECORD_COUNT, AMOUNT_TOTAL,
       SHA256, FILE_PATH, STATUS
FROM RECON_BATCH_PART
WHERE BATCH_ID = #{batchId,jdbcType=VARCHAR}
  AND SOURCE_NAME = #{source,jdbcType=VARCHAR}
  AND FILE_TYPE = #{fileType,jdbcType=VARCHAR}
  AND PART_NO = #{partNo,jdbcType=NUMERIC}

mapper.update:
UPDATE RECON_BATCH_PART
SET STATUS = #{status,jdbcType=VARCHAR}, RETRY_COUNT = RETRY_COUNT + 1, UPDATED_AT = SYSTIMESTAMP
WHERE BATCH_ID = #{batchId,jdbcType=VARCHAR}
  AND SOURCE_NAME = #{source,jdbcType=VARCHAR}
  AND FILE_TYPE = #{fileType,jdbcType=VARCHAR}
  AND PART_NO = #{partNo,jdbcType=NUMERIC}

mapper.select:
SELECT BATCH_ID, SOURCE_NAME, FILE_TYPE, PART_NO, BYTE_COUNT, RECORD_COUNT, AMOUNT_TOTAL,
       SHA256, FILE_PATH, STATUS
FROM RECON_BATCH_PART
WHERE BATCH_ID = #{batchId,jdbcType=VARCHAR}
  AND SOURCE_NAME = #{source,jdbcType=VARCHAR}
  AND FILE_TYPE = #{fileType,jdbcType=VARCHAR}
  AND STATUS = 'RECEIVED'
ORDER BY PART_NO

SELECT COUNT(*) PART_COUNT, NVL(SUM(RECORD_COUNT),0) RECORD_SUM, NVL(SUM(AMOUNT_TOTAL),0) AMOUNT_SUM
FROM RECON_BATCH_PART
WHERE BATCH_ID = #{batchId,jdbcType=VARCHAR}
  AND SOURCE_NAME = #{source,jdbcType=VARCHAR}
  AND FILE_TYPE = #{fileType,jdbcType=VARCHAR}
  AND STATUS = 'RECEIVED'
